package io.github.jesterportfolio.hearth.economy;

import io.github.jesterportfolio.hearth.survival.housing.*;
import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;

/** 기존 경제 realm 잠금과 같은 worker/계정으로 주택 결제를 원자 처리합니다. payload는 수정하지 않습니다. */
public final class HousingStore {
 private final PostgresProgressStore db;private final EconomyStore economy;private final UUID realm;private final HousingSettings settings;
 public HousingStore(PostgresProgressStore db,EconomyStore economy,UUID realm,HousingSettings settings){this.db=db;this.economy=economy;this.realm=realm;this.settings=settings;}
 private static StorageFailure fail(String s){return new StorageFailure("housing",s);}
 private void access(Connection c,ServerProgressAccess.Context ctx)throws Exception{if(!realm.equals(ctx.storyRunId()))throw fail("HOUSING_REALM");economy.housingLock(c,ctx);}
 @FunctionalInterface private interface Work<T>{T run(Connection c)throws Exception;}
 private <T>CompletionStage<T> tx(String name,ServerProgressAccess.Context ctx,Work<T> work){return db.module(name,c->{c.setAutoCommit(false);try{access(c,ctx);T v=work.run(c);c.commit();return v;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}});}
 private PreparedStatement st(Connection c,String sql,Object... args)throws SQLException{var s=c.prepareStatement(sql);for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;}
 private void update(Connection c,String sql,Object...args)throws SQLException{try(var s=st(c,sql,args)){if(s.executeUpdate()!=1)throw fail("CAS_CONFLICT");}}
 public CompletionStage<Void> open(){return tx("housing_open",economy.context(realm,new UUID(0,0)),c->{boolean found;try(var s=st(c,"SELECT geometry_hash FROM hearth_economy.housing_policy WHERE realm_id=?",realm);var r=s.executeQuery()){found=r.next();if(found&&!r.getString(1).equals(settings.geometryHash()))throw fail("HOUSING_GEOMETRY_MISMATCH");}if(!found){if(!settings.allowNew())throw fail("HOUSING_POLICY_MISSING");update(c,"INSERT INTO hearth_economy.housing_policy VALUES(?,?)",realm,settings.geometryHash());}var catalog=settings.catalog();try(var s=st(c,"SELECT hash,payload FROM hearth_economy.housing_catalog WHERE realm_id=? AND version=?",realm,catalog.version());var r=s.executeQuery()){if(r.next()){if(!r.getString(1).equals(catalog.hash())||!r.getString(2).equals(catalog.packed()))throw fail("HOUSING_PRICE_VERSION_MISMATCH");}else{if(!settings.allowNew())throw fail("HOUSING_CATALOG_MISSING");update(c,"INSERT INTO hearth_economy.housing_catalog VALUES(?,?,?,?)",realm,catalog.version(),catalog.hash(),catalog.packed());}}return null;});}
 private House house(ResultSet r)throws SQLException{return new House(r.getObject("house_id",UUID.class),r.getObject("owner_id",UUID.class),r.getString("version"),r.getInt("tier"),r.getInt("width"),r.getLong("paid"),r.getLong("seed"),r.getObject("world_uuid",UUID.class),Phase.valueOf(r.getString("phase")),r.getLong("revision"));}
 private Optional<House> find(Connection c,String column,UUID id)throws Exception{if(!Set.of("house_id","owner_id").contains(column))throw new IllegalArgumentException();try(var s=st(c,"SELECT * FROM hearth_economy.house WHERE realm_id=? AND "+column+"=?",realm,id);var r=s.executeQuery()){return r.next()?Optional.of(house(r)):Optional.empty();}}
 private House owned(Connection c,ServerProgressAccess.Context ctx,UUID id,long revision)throws Exception{var h=find(c,"house_id",id).orElseThrow(()->fail("HOUSING_MISSING"));if(!h.owner().equals(ctx.playerId())||h.revision()!=revision||h.phase()!=Phase.ACTIVE)throw fail("HOUSING_STALE_OR_OWNER");return h;}
 private HousingSettings.Catalog catalog(Connection c,String version)throws Exception{try(var s=st(c,"SELECT payload,hash FROM hearth_economy.housing_catalog WHERE realm_id=? AND version=?",realm,version);var r=s.executeQuery()){if(!r.next())throw fail("HOUSING_CATALOG_MISSING");var catalog=HousingSettings.Catalog.unpack(version,r.getString(1));if(!catalog.hash().equals(r.getString(2)))throw fail("HOUSING_CATALOG_CORRUPT");return catalog;}}
 private static Request request(ResultSet r)throws SQLException{return new Request(r.getObject("request_id",UUID.class),r.getObject("house_id",UUID.class),r.getObject("owner_id",UUID.class),r.getString("version"),r.getInt("tier"),r.getLong("cost"),r.getLong("revision"),r.getBoolean("paid"));}
 private Optional<Request> request(Connection c,UUID id)throws Exception{try(var s=st(c,"SELECT * FROM hearth_economy.housing_request WHERE realm_id=? AND request_id=?",realm,id);var r=s.executeQuery()){return r.next()?Optional.of(request(r)):Optional.empty();}}
 public static CompletionStage<Optional<Request>> inspectExisting(PostgresProgressStore db,EconomyStore economy,ServerProgressAccess.Context ctx,UUID id){return db.module("housing_readonly_receipt",c->{economy.housingLock(c,ctx);try(var s=c.prepareStatement("SELECT * FROM hearth_economy.housing_request WHERE realm_id=? AND request_id=?")){s.setObject(1,ctx.storyRunId());s.setObject(2,id);try(var r=s.executeQuery()){if(!r.next())return Optional.empty();var saved=request(r);if(!saved.owner().equals(ctx.playerId()))throw fail("HOUSING_OWNER");return Optional.of(saved);}}});}
 public CompletionStage<Optional<Request>> inspect(ServerProgressAccess.Context ctx,UUID id){return tx("housing_inspect",ctx,c->{var r=request(c,id);if(r.isPresent()&&!r.get().owner().equals(ctx.playerId()))throw fail("HOUSING_OWNER");return r;});}
 private long balance(Connection c,UUID owner)throws Exception{try(var s=st(c,"SELECT balance FROM hearth_economy.account WHERE realm_id=? AND player_uuid=? FOR UPDATE",realm,owner);var r=s.executeQuery()){if(!r.next())throw fail("HOUSING_ACCOUNT");return r.getLong(1);}}
 private static void valid(BooleanSupplier valid){if(!valid.getAsBoolean())throw fail("STALE_CONTEXT");}
 public CompletionStage<Request> reserve(ServerProgressAccess.Context ctx,UUID id,int tier,long expected,BooleanSupplier valid){return tx("housing_reserve",ctx,c->{valid(valid);var old=request(c,id);if(old.isPresent()){var r=old.get();if(!r.owner().equals(ctx.playerId())||r.tier()!=tier)throw fail("HOUSING_REQUEST_CONFLICT");return r;}if(!settings.purchases())throw fail("HOUSING_PURCHASE_DISABLED");var found=find(c,"owner_id",ctx.playerId());House h;String version=found.map(House::version).orElse(settings.catalog().version());var catalog=catalog(c,version);long cost=catalog.cost(found.map(House::tier).orElse(-1),tier);if(balance(c,ctx.playerId())<cost)throw fail("ECON_FUNDS");
  if(found.isEmpty()){if(expected!=-1)throw fail("HOUSING_STALE");var target=catalog.tiers().get(tier);UUID house=UUID.randomUUID();update(c,"INSERT INTO hearth_economy.house VALUES(?,?,?,?,?,?,0,?,NULL,'PREPARING',0)",realm,house,ctx.playerId(),version,tier,target.width(),java.util.concurrent.ThreadLocalRandom.current().nextLong());h=find(c,"house_id",house).orElseThrow();}else{h=owned(c,ctx,found.get().id(),expected);update(c,"UPDATE hearth_economy.house SET phase='PREPARING',revision=revision+1 WHERE realm_id=? AND house_id=? AND revision=?",realm,h.id(),expected);h=find(c,"house_id",h.id()).orElseThrow();}
  update(c,"INSERT INTO hearth_economy.housing_request VALUES(?,?,?,?,?,?,?,?,false)",realm,id,h.id(),ctx.playerId(),version,tier,cost,h.revision());valid(valid);return new Request(id,h.id(),ctx.playerId(),version,tier,cost,h.revision(),false);});}
 public CompletionStage<House> prepared(ServerProgressAccess.Context ctx,Request req,UUID world){return tx("housing_prepared",ctx,c->{var r=request(c,req.id()).orElseThrow();var h=find(c,"house_id",r.house()).orElseThrow();if(!r.equals(req)||!h.owner().equals(ctx.playerId())||h.phase()!=Phase.PREPARING||h.revision()!=req.revision()||h.world()!=null&&!h.world().equals(world))throw fail("HOUSING_PREPARED_STALE");update(c,"UPDATE hearth_economy.house SET world_uuid=? WHERE realm_id=? AND house_id=? AND revision=?",world,realm,h.id(),h.revision());return find(c,"house_id",h.id()).orElseThrow();});}
 public CompletionStage<House> commit(ServerProgressAccess.Context ctx,Request req,BooleanSupplier valid,EconomyStore.Probe probe){return tx("housing_commit",ctx,c->{valid(valid);var r=request(c,req.id()).orElseThrow();if(!r.owner().equals(ctx.playerId())||r.tier()!=req.tier()||!r.house().equals(req.house()))throw fail("HOUSING_REQUEST_CONFLICT");var h=find(c,"house_id",r.house()).orElseThrow();if(r.paid())return h;if(h.phase()!=Phase.PREPARING||h.revision()!=r.revision()||h.world()==null)throw fail("HOUSING_NOT_PREPARED");long before=balance(c,ctx.playerId());if(before<r.cost())throw fail("ECON_FUNDS");var target=catalog(c,r.version()).tiers().get(r.tier());update(c,"UPDATE hearth_economy.account SET balance=balance-? WHERE realm_id=? AND player_uuid=? AND balance=?",r.cost(),realm,ctx.playerId(),before);update(c,"UPDATE hearth_economy.house SET tier=?,width=?,paid=?,phase='APPLYING',revision=revision+1 WHERE realm_id=? AND house_id=? AND revision=?",r.tier(),target.width(),target.price(),realm,h.id(),h.revision());update(c,"UPDATE hearth_economy.housing_request SET paid=true WHERE realm_id=? AND request_id=? AND NOT paid",realm,r.id());valid(valid);if(probe==EconomyStore.Probe.ROLLBACK)throw new SQLException("Housing fixture rollback","23514");return find(c,"house_id",h.id()).orElseThrow();}).thenApply(h->{if(probe==EconomyStore.Probe.COMMIT_UNKNOWN)throw fail("COMMIT_UNKNOWN");return h;});}
 public CompletionStage<House> activate(ServerProgressAccess.Context ctx,Request req){return tx("housing_activate",ctx,c->{var r=request(c,req.id()).orElseThrow();var h=find(c,"house_id",r.house()).orElseThrow();if(!r.owner().equals(ctx.playerId())||!r.paid()||h.world()==null||h.tier()!=r.tier())throw fail("HOUSING_ACTIVATE");if(h.phase()==Phase.ACTIVE)return h;if(h.phase()!=Phase.APPLYING)throw fail("HOUSING_ACTIVATE");update(c,"UPDATE hearth_economy.house SET phase='ACTIVE',revision=revision+1 WHERE realm_id=? AND house_id=? AND revision=?",realm,h.id(),h.revision());return find(c,"house_id",h.id()).orElseThrow();});}
 public CompletionStage<Void> invite(ServerProgressAccess.Context ctx,UUID house,long revision,UUID player,Role role,BooleanSupplier valid){return tx("housing_invite",ctx,c->{valid(valid);var h=owned(c,ctx,house,revision);if(player.equals(ctx.playerId()))throw fail("HOUSING_SELF_INVITE");balance(c,player);try(var s=st(c,"SELECT count(*) FROM hearth_economy.house_member WHERE realm_id=? AND house_id=?",realm,house);var r=s.executeQuery()){r.next();if(r.getInt(1)>=settings.maxMembers())throw fail("HOUSING_MEMBERS_FULL");}update(c,"INSERT INTO hearth_economy.house_member VALUES(?,?,?,?,false)",realm,house,player,role.name());bump(c,h);valid(valid);return null;});}
 public CompletionStage<Void> accept(ServerProgressAccess.Context ctx,UUID house,long revision,boolean yes,BooleanSupplier valid){return tx("housing_accept",ctx,c->{valid(valid);var h=find(c,"house_id",house).orElseThrow();if(h.phase()!=Phase.ACTIVE||h.revision()!=revision)throw fail("HOUSING_STALE");if(yes)update(c,"UPDATE hearth_economy.house_member SET accepted=true WHERE realm_id=? AND house_id=? AND player_id=? AND NOT accepted",realm,house,ctx.playerId());else update(c,"DELETE FROM hearth_economy.house_member WHERE realm_id=? AND house_id=? AND player_id=? AND NOT accepted",realm,house,ctx.playerId());bump(c,h);valid(valid);return null;});}
 public CompletionStage<Void> remove(ServerProgressAccess.Context ctx,UUID house,long revision,UUID player,BooleanSupplier valid){return tx("housing_remove",ctx,c->{valid(valid);var h=find(c,"house_id",house).orElseThrow();if(h.phase()!=Phase.ACTIVE||h.revision()!=revision||!h.owner().equals(ctx.playerId())&&!player.equals(ctx.playerId())||h.owner().equals(player))throw fail("HOUSING_STALE_OR_OWNER");update(c,"DELETE FROM hearth_economy.house_member WHERE realm_id=? AND house_id=? AND player_id=?",realm,house,player);bump(c,h);valid(valid);return null;});}
 private void bump(Connection c,House h)throws Exception{update(c,"UPDATE hearth_economy.house SET revision=revision+1 WHERE realm_id=? AND house_id=? AND revision=?",realm,h.id(),h.revision());}
 public CompletionStage<String> claimPlot(ServerProgressAccess.Context ctx,BooleanSupplier valid){return tx("housing_plot",ctx,c->{valid(valid);balance(c,ctx.playerId());var used=new HashSet<String>();try(var s=st(c,"SELECT player_id,plot_id FROM hearth_economy.housing_plot WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next()){if(r.getObject(1,UUID.class).equals(ctx.playerId()))return r.getString(2);used.add(r.getString(2));}}String slot=settings.plots().stream().map(HousingSettings.Plot::id).filter(id->!used.contains(id)).findFirst().orElseThrow(()->fail("HOUSING_PLOTS_FULL"));update(c,"INSERT INTO hearth_economy.housing_plot VALUES(?,?,?)",realm,ctx.playerId(),slot);valid(valid);return slot;});}
 public CompletionStage<List<UUID>> players(ServerProgressAccess.Context ctx){return tx("housing_players",ctx,c->{var all=new ArrayList<UUID>();try(var s=st(c,"SELECT player_uuid FROM hearth_economy.account WHERE realm_id=? ORDER BY player_uuid LIMIT 10001",realm);var r=s.executeQuery()){while(r.next())all.add(r.getObject(1,UUID.class));}if(all.size()>10000)throw fail("HOUSING_METADATA_LIMIT");return List.copyOf(all);});}
 public CompletionStage<Snapshot> snapshot(){return tx("housing_snapshot",economy.context(realm,new UUID(0,0)),c->{var houses=new ArrayList<House>();try(var s=st(c,"SELECT * FROM hearth_economy.house WHERE realm_id=? ORDER BY house_id LIMIT 10001",realm);var r=s.executeQuery()){while(r.next())houses.add(house(r));}if(houses.size()>10000)throw fail("HOUSING_METADATA_LIMIT");var members=new ArrayList<Member>();try(var s=st(c,"SELECT * FROM hearth_economy.house_member WHERE realm_id=? ORDER BY house_id,player_id LIMIT 640001",realm);var r=s.executeQuery()){while(r.next())members.add(new Member(r.getObject("house_id",UUID.class),r.getObject("player_id",UUID.class),Role.valueOf(r.getString("role")),r.getBoolean("accepted")));}if(members.size()>640000)throw fail("HOUSING_METADATA_LIMIT");var plots=new HashMap<UUID,String>();try(var s=st(c,"SELECT player_id,plot_id FROM hearth_economy.housing_plot WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next())plots.put(r.getObject(1,UUID.class),r.getString(2));}var players=new ArrayList<UUID>();try(var s=st(c,"SELECT player_uuid FROM hearth_economy.account WHERE realm_id=? ORDER BY player_uuid LIMIT 10001",realm);var r=s.executeQuery()){while(r.next())players.add(r.getObject(1,UUID.class));}if(players.size()>10000)throw fail("HOUSING_METADATA_LIMIT");var catalogs=new HashMap<String,HousingSettings.Catalog>();try(var s=st(c,"SELECT version FROM hearth_economy.housing_catalog WHERE realm_id=?",realm);var r=s.executeQuery()){while(r.next()){String v=r.getString(1);catalogs.put(v,catalog(c,v));}}return new Snapshot(houses,members,plots,players,catalogs);});}
}
